"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["66511"],{86095(e){e.exports=JSON.parse('{"id":"FIN-667","slug":"incremental-cash-flow","term":"Incremental Cash Flow","also_known_as":[],"difficulty":"Intermediate","definition":"Incremental cash flow is the additional cash a company expects to receive or pay out as a direct result of undertaking a specific project or decision, compared with not doing it.","explanation":["When evaluating an investment, the key question is how the company\'s future cash flows will change if it goes ahead. Only cash flows that would not happen otherwise should be counted.","Incremental cash flows include the initial investment, extra revenues, extra operating costs, changes in working capital, taxes and any cash received when the project ends, such as from selling equipment.","For example, a company launching a new product expects it to bring in 500,000 a year in sales, but it will also reduce sales of an existing product by 100,000. The incremental revenue is 400,000, not 500,000.","Some cash flows should be excluded. Sunk costs, such as money already spent on research, are irrelevant because they cannot be recovered. Fixed overheads that will continue regardless of the decision should not be counted. Opportunity costs, such as income from renting out a building the project will now use, should be included.","Incremental cash flows form the basis of capital budgeting tools such as net present value and internal rate of return. Getting them right is essential for making sound investment decisions."],"note":"","total":1500,"prev":{"slug":"income-tax-expense","term":"Income Tax Expense"},"next":{"slug":"incremental-cost","term":"Incremental Cost"}}')}}]);